function emitDebris(pos,normal,final=false){if(debris.length>=340)return;stats.debrisEmitted++;const r=rand(),base=damage>.4?[.055,.036,.022]:[.18,.091,.028],size=.075+rand()*.21;debris.push({p:pos.map((v,i)=>v+(rand()-.5)*(final?2.8:.6)),v:[normal[0]*(1.2+rand()*1.8)+(rand()-.5)*3,1.8+rand()*3.5,normal[2]*(1.2+rand()*1.8)+(rand()-.5)*3],r:[rand()*TAU,rand()*TAU,rand()*TAU],spin:[(rand()-.5)*5,(rand()-.5)*5,(rand()-.5)*5],size:[size*(.6+rand()),size*(.7+rand()*2.5),size*(.5+rand())],color:base.map(v=>v*(.6+r*.8)),age:0,life:3.5+rand()*2.2,bounces:0})}
